mapper.select:
select acs.ai_chat_session_id as aiChatSessionId, acs.test_project_id as testProjectId, acs.user_id as userId, acs.session_scene as sessionScene, acs.biz_ref_json as bizRefJson, acs.current_model_id as currentModelId, acs.thinking_enabled as thinkingEnabled, acs.session_title as sessionTitle, acs.context_summary as contextSummary, acs.summary_message_count as summaryMessageCount, acs.summary_updated_at as summaryUpdatedAt, acs.create_time as createTime from ai_chat_session acs
and acs.test_project_id = #{testProjectId}
and acs.user_id = #{userId}
and acs.session_scene = #{sessionScene}
and acs.current_model_id = #{currentModelId}
and acs.session_title like concat('%', #{sessionTitle}, '%')
and acs.biz_ref_json = #{bizRefJson}
and CAST(JSON_UNQUOTE(JSON_EXTRACT(acs.biz_ref_json, '$.testFlowId')) AS CHAR) = CAST(#{testFlowId} AS CHAR)
and CAST(JSON_UNQUOTE(JSON_EXTRACT(acs.biz_ref_json, '$.testProjectApiId')) AS CHAR) = CAST(#{testProjectApiId} AS CHAR)
order by acs.create_time desc

select count(1)
from ai_chat_session acs


        and acs.test_project_id = #{testProjectId}


        and acs.user_id = #{userId}


        and acs.session_scene = #{sessionScene}


        and acs.current_model_id = #{currentModelId}


        and acs.session_title like concat('%', #{sessionTitle}, '%')

select acs.ai_chat_session_id, acs.test_project_id, acs.user_id, acs.session_scene, acs.biz_ref_json, acs.current_model_id, acs.thinking_enabled, acs.session_title, acs.context_summary, acs.summary_message_count, acs.summary_updated_at, acs.create_time from ai_chat_session acs
and acs.test_project_id = #{testProjectId}
and acs.user_id = #{userId}
and acs.session_scene = #{sessionScene}
and acs.current_model_id = #{currentModelId}
and acs.session_title like concat('%', #{sessionTitle}, '%')
order by acs.ai_chat_session_id desc limit 1
